cd /tmp; kubectl -n otel-demo exec deploy/load-generator -- python3 -c '
import urllib.request,time
for u in ["/","/api/products","/api/cart?sessionId=x","/api/recommendations?productIds=","/api/data","/api/currency"]:
    t=time.time()
    try:
        r=urllib.request.urlopen("http://frontend-proxy:8080"+u,timeout=15); print(u,r.status,round(time.time()-t,2))
    except Exception as e:
        print(u,"ERR",getattr(e,"code",e),round(time.time()-t,2))
' 2>&1 | head -20

cd /tmp; cat > /tmp/promq.py <<'EOF'
import urllib.request, urllib.parse, json, sys
base = "http://prometheus-kube-prometheus-prometheus.prometheus.svc.cluster.local:9090/api/v1/"
def get(path, **params):
    url = base + path + ("?" + urllib.parse.urlencode(params) if params else "")
    return json.load(urllib.request.urlopen(url, timeout=15))
if sys.argv[1] == "alerts":
    for a in get("alerts")["data"]["alerts"]:
        print(a["state"], a["labels"].get("alertname"), a["labels"].get("service_name", ""), a.get("value", ""))
else:
    for r in get("query", query=sys.argv[1])["data"]["result"]:
        print(r["metric"], r["value"][1])
EOF
kubectl -n otel-demo cp /tmp/promq.py load-generator-$(kubectl -n otel-demo get pods -l opentelemetry.io/name=load-generator -o name | cut -d/ -f2 | sed 's/load-generator-//'):/tmp/promq.py 2>&1 | tail -2; LG=$(kubectl -n otel-demo get pods -l opentelemetry.io/name=load-generator -o name | cut -d/ -f2); kubectl -n otel-demo cp /tmp/promq.py $LG:/tmp/promq.py && kubectl -n otel-demo exec $LG -- python3 /tmp/promq.py alerts 2>&1 | head -20

